import { effectiveStats } from './Equipment.js';
import { abilityModifier } from './Modifiers.js';
import { d20Penalty } from './Exhaustion.js';
import { slotsForCaster, slotPoolsForCaster, casterLevelContribution } from './SpellSlots.js';
import { characterProficiency, getClasses } from './Multiclass.js';
import { casterDefFor, isCasterRef } from './ClassCasting.js';
import { DEFAULT_CLASSES } from '../data/classes.js';
import { memoizeByIdentity } from '../util/memoize.js';
import { clamp } from '../util/num.js';
import { hasAncientSecrets, tomeCantrips, tomeRituals } from './PactTome.js';

/** @typedef {import('../types/class.js').ClassDef} ClassDef */
/** @typedef {import('../types/class.js').CasterType} CasterType */
/** @typedef {import('../types/class.js').ClassRef} ClassRef */
/** @typedef {import('../types/spell.js').Ability} Ability */
/** @typedef {import('../types/entities.js').Character} Character */
/** @typedef {import('../types/entities.js').SpellCaster} SpellCaster */

/**
 * The playable classes. The definitions themselves live in data/classes.js
 * (library-kind shaped, with a stable id and name per entry). This module
 * holds the logic that reads them.
 * @type {ClassDef[]}
 */
export const CLASS_LIST = DEFAULT_CLASSES;

/** The classes indexed by id, for O(1) lookup.
 * @type {Map<string, ClassDef>} */
const CLASS_BY_ID = new Map(CLASS_LIST.map((c) => [c.id, c]));

/**
 * The class definition for an id, or null for an unknown or absent class (a
 * classless legacy character).
 * @param {string | undefined | null} classId
 * @returns {ClassDef | null}
 */
export function getClass(classId) {
  return (classId && CLASS_BY_ID.get(classId)) || null;
}

/**
 * A featuresByLevel entry normalized to `{ name, effects }`. A plain string
 * is a display-only feature and comes back with no effects. The result is a
 * fresh object; the catalog entry is never touched.
 * @param {string | import('../types/class.js').ClassFeatureDef} entry
 * @returns {{ name: string, effects: import('../types/class.js').ClassFeatureEffect[] }}
 */
export function featureEntry(entry) {
  if (typeof entry === 'string') return { name: entry, effects: [] };
  return { name: entry.name, effects: Array.isArray(entry.effects) ? [...entry.effects] : [] };
}

/**
 * Whether a class casts spells at all (full, half, or pact), by class alone.
 * A subclass that adds casting (the Eldritch Knight) does not count here.
 * Ask `isCasterRef` about a whole class membership.
 * @param {string | undefined | null} classId
 * @returns {boolean}
 */
export function isCasterClass(classId) {
  const def = getClass(classId);
  return !!def && def.casterType !== 'none';
}

/**
 * The caster definition for one of the character's classes: its class
 * membership with the subclass applied (see `ClassCasting.casterDefFor`).
 * A class the character does not hold reads the plain class definition, so
 * a caller that names any class still gets its fields. Null for an unknown
 * class.
 * @param {SpellCaster} character
 * @param {string | undefined | null} classId
 * @returns {ClassDef | null}
 */
export function casterDefOf(character, classId) {
  if (!classId) return null;
  const ref = getClasses(character).find((r) => r.classId === classId);
  return ref ? casterDefFor(ref) : getClass(classId);
}

/**
 * Slot counts per spell level for a class at a character level, driven by the
 * class's caster type. A non-caster, pact caster, or unknown class gets no
 * leveled slots here. A different function handles pact magic. `subclass`
 * applies a casting subclass such as the Eldritch Knight.
 * @param {string | undefined | null} classId
 * @param {number} characterLevel
 * @param {string} [subclass]
 * @returns {number[]} index 0 = spell level 1
 */
export function slotsForClass(classId, characterLevel, subclass) {
  if (!classId) return [];
  const def = casterDefFor({ classId, level: characterLevel, subclass });
  if (!def) return [];
  return slotsForCaster(def.casterType, characterLevel);
}

/**
 * The full spell-slot pools for a class at a character level, all at full.
 * This is caster-type-aware (full, half, or third), so a creature caster
 * gets exactly the slots its class and subclass grant, and a pact caster
 * gets its pact pool. Empty for a non-caster or an unknown class.
 * @param {string | undefined | null} classId
 * @param {number} characterLevel
 * @param {string} [subclass]
 * @returns {import('../types/entities.js').ResourcePool[]}
 */
export function casterSlots(classId, characterLevel, subclass) {
  if (!classId) return [];
  const def = casterDefFor({ classId, level: characterLevel, subclass });
  if (!def) return [];
  return slotPoolsForCaster(def.casterType, characterLevel);
}

/**
 * Cantrips known for a class at a character level, from its cantrip curve.
 * Returns 0 for classes that know no cantrips, or for an unknown class.
 * Levels past the curve read its last entry.
 * @param {string | undefined | null} classId
 * @param {number} characterLevel
 * @param {string} [subclass]
 * @returns {number}
 */
export function cantripsKnownForClass(classId, characterLevel, subclass) {
  if (!classId) return 0;
  const def = casterDefFor({ classId, level: characterLevel, subclass });
  if (!def || def.cantripsKnown.length === 0) return 0;
  const idx = clamp(Math.floor(characterLevel) || 1, 1, def.cantripsKnown.length) - 1;
  return def.cantripsKnown[idx];
}

/**
 * The unarmored defense formulas the character's classes grant, in class-list
 * order. Empty for a character with no granting class. A build that stacked
 * two granting classes returns both, because this function reports what the
 * classes say and leaves the choice between them to `Armor.armorClass`.
 * An unknown class id contributes nothing.
 * @param {Character} character
 * @returns {import('../types/class.js').UnarmoredDefense[]}
 */
export function unarmoredDefenses(character) {
  return getClasses(character)
    .map((ref) => getClass(ref.classId)?.unarmoredDefense)
    .filter((def) => !!def);
}

/**
 * The character's caster classes: every class-list entry whose class casts
 * (full, half, third, or pact), with its subclass applied, so an Eldritch
 * Knight counts. Empty for a martial or classless character.
 * @param {SpellCaster} character
 * @returns {ClassRef[]}
 */
export function casterClassRefs(character) {
  return getClasses(character).filter(isCasterRef);
}

/**
 * Whether the character can cast rituals: true when any of its caster
 * classes has ritual casting (Bard, Cleric, Druid, Wizard), or when a
 * warlock has Book of Ancient Secrets. With `spellId`, the warlock counts
 * only for a ritual in its Book of Shadows. A ritual spell
 * is castable without a slot only by a caster whose class grants the
 * feature. This gates the cast dialog's ritual option.
 * @param {SpellCaster} character
 * @param {string} [spellId]
 * @returns {boolean}
 */
export function hasRitualCasting(character, spellId) {
  if (casterClassRefs(character).some((ref) => !!casterDefFor(ref)?.ritual)) return true;
  if (!hasAncientSecrets(character)) return false;
  return spellId === undefined || tomeRituals(character).includes(spellId);
}

/**
 * The character's first caster class, or null. This is the class whose
 * ability powers spells when a caller does not name one.
 * @param {SpellCaster} character
 * @returns {ClassRef | null}
 */
export function primaryCasterClass(character) {
  return casterClassRefs(character)[0] ?? null;
}

/**
 * Whether any of the character's caster classes prepares its spells (Cleric,
 * Druid, Paladin, Wizard). This gates the prepared count and the Prepare
 * actions. A known-rule caster (Bard, Ranger, Sorcerer, Warlock) never
 * prepares.
 * @param {Character} character
 * @returns {boolean}
 */
export function hasPreparedCaster(character) {
  return casterClassRefs(character).some((ref) => casterDefFor(ref)?.knownRule === 'prepared');
}

/**
 * The modifier of a caster's spell ability, or null when the character has no
 * caster class or lacks that ability score. `classId` picks which class's
 * ability to read. It defaults to the first caster class.
 * @param {SpellCaster} character
 * @param {string} [classId]
 * @returns {number | null}
 */
export function spellAbilityModifier(character, classId) {
  const def = casterDefOf(character, classId ?? primaryCasterClass(character)?.classId);
  if (!def || !def.spellAbility) return null;
  // A character reads its equipped buffs, so a +4 INT headband raises the
  // spell DC with the INT check. A creature view carries no equipment.
  const stats =
    'equipment' in character
      ? effectiveStats(/** @type {Character} */ (character))
      : character.stats;
  const score = stats?.[def.spellAbility];
  if (typeof score !== 'number') return null;
  return abilityModifier(score);
}

/**
 * A caster's spell save DC: 8 plus proficiency bonus plus spell-ability
 * modifier. Proficiency reads the sum of the assigned class levels (the 5e
 * multiclass rule, see `Multiclass.characterProficiency`), unless the caster carries an explicit `proficiency` (a rated
 * creature's view does, from the challenge-rating ladder). The ability
 * comes from `classId`, defaulting to the first caster class. Returns null
 * for a non-caster.
 * @param {SpellCaster} character
 * @param {string} [classId]
 * @returns {number | null}
 */
export function spellSaveDC(character, classId) {
  const mod = spellAbilityModifier(character, classId);
  if (mod === null) return null;
  return 8 + casterProficiency(character) + mod;
}

/**
 * A caster's spell attack bonus: proficiency bonus plus spell-ability
 * modifier, with the same class selection as `spellSaveDC`. Returns null
 * for a non-caster.
 *
 * Exhaustion takes 2 off for each of its levels, because a spell attack is a
 * d20 test. `spellSaveDC` above deliberately has no such term. A save DC is a
 * number the target rolls against, not a roll the caster makes, so exhaustion
 * never lowers it.
 * @param {SpellCaster} character
 * @param {string} [classId]
 * @returns {number | null}
 */
export function spellAttackBonus(character, classId) {
  const mod = spellAbilityModifier(character, classId);
  if (mod === null) return null;
  return casterProficiency(character) + mod + d20Penalty(character);
}

/**
 * The proficiency bonus a caster's spells use: the explicit `proficiency`
 * of the view where one is stamped, else the level ladder.
 * @param {SpellCaster} character
 * @returns {number}
 */
function casterProficiency(character) {
  return character.proficiency ?? characterProficiency(character);
}

/**
 * How many cantrips a character can know: each caster class's cantrip curve
 * read at its own class level, summed, plus the Book of Shadows cantrips of
 * a Pact of the Tome warlock, which do not count against the limit. Returns
 * 0 for a non-caster or a classless character.
 *
 * This value is memoized on the character, like `preparedLimit`. The
 * spellbook panel asks for both limits once per listed spell, and
 * `preparedLimit` re-resolves a spell ability modifier per class each time.
 */
export const cantripLimit = memoizeByIdentity(countCantripsKnown);

/**
 * @param {Character} character
 * @returns {number}
 */
function countCantripsKnown(character) {
  return casterClassRefs(character).reduce(
    (sum, ref) => sum + cantripsKnownForClass(ref.classId, ref.level, ref.subclass),
    tomeCantrips(character).length,
  );
}

/**
 * How many leveled spells a character can have prepared: per prepared-rule
 * caster class, its spell-ability modifier plus its caster level, at least 1
 * (the 5e prepared-caster rule), summed across those classes. The caster
 * level is the whole class level for a full caster (Cleric, Druid, Wizard)
 * and half the class level, rounded down, for a half caster (Paladin), the
 * same weighting the multiclass slot table uses. Returns 0 for
 * a non-caster, or for a caster whose classes all cast from their known
 * list, since those classes grant no prepared slots. This value is
 * memoized on the character.
 */
export const preparedLimit = memoizeByIdentity(countPreparedAllowed);

/**
 * @param {Character} character
 * @returns {number}
 */
function countPreparedAllowed(character) {
  return casterClassRefs(character).reduce((sum, ref) => {
    const def = casterDefFor(ref);
    if (def?.knownRule !== 'prepared') return sum;
    const mod = spellAbilityModifier(character, ref.classId);
    if (mod === null) return sum;
    return sum + Math.max(1, mod + casterLevelContribution(def.casterType, ref.level));
  }, 0);
}
